package com.company.iaf.qms.engineering.interfaces.controller;
import com.company.iaf.qms.engineering.infrastructure.persistence.InspectionStandardService;import com.company.iaf.qms.engineering.interfaces.dto.*;import com.company.iaf.shared.result.Result;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/qms/drawing-revisions/{revisionId}/inspection-standard") public class QmsInspectionStandardController{private final InspectionStandardService service;public QmsInspectionStandardController(InspectionStandardService s){service=s;}@GetMapping public Result<InspectionStandardResponse> get(@PathVariable("revisionId") long revisionId){return Result.ok(service.get(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),revisionId));}@PostMapping("/generate") public Result<InspectionStandardResponse> generate(@PathVariable("revisionId") long revisionId){return Result.ok(service.generate(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),revisionId));}@PutMapping("/{id}") public Result<InspectionStandardResponse> update(@PathVariable("revisionId") long revisionId,@PathVariable("id") long id,@Valid @RequestBody InspectionStandardUpdateRequest q){return Result.ok(service.update(QmsRequestContext.tenantId(),QmsRequestContext.orgId(),revisionId,id,q));}}
